def transform(g):
    h,w=len(g),len(g[0])
    pluses=[]
    for r in range(1,h-1):
        for c in range(1,w-1):
            if g[r][c]!=3 and g[r-1][c]==3 and g[r+1][c]==3 and g[r][c-1]==3 and g[r][c+1]==3:
                pluses.append((r,c,g[r][c]))
    vcols={}; hrows={}
    for r,c,col in pluses:
        if col!=0:
            hrows[r]=col; vcols[c]=col
    out=[row[:] for row in g]
    for r,col in hrows.items():
        out[r]=[col]*w
    for c,col in vcols.items():
        for r in range(h): out[r][c]=col
    # restore 3s and uncovered cells
    for r in range(h):
        for c in range(w):
            onh = r in hrows; onv = c in vcols
            if not (onh or onv): out[r][c]=g[r][c]
            elif g[r][c]==3: out[r][c]=3
    return out
